"""Records what a program does when a person uses it, for the gadgets of BlitzPlus that media.py can't show.

The example is run as it is under a bare X server, and a script of real mouse and keyboard input is played at its
window with xdotool. A screenshot of the window is taken at the start and after every step. The script is in the
media lines at the top of the example, which wiki.py hides from the page:

  ;media interact gadgets/button.gif 4     Saves every screenshot as a GIF of 4 frames per second, or the last as a PNG.
  ;media click 60 40                       Moves the mouse there (x and y of the program's window) and clicks.
  ;media rclick 60 40                      The same with the right button.
  ;media move 60 40                        Moves the mouse.
  ;media drag 10 40 90 40                  Presses at the first point, moves to the second and lets go.
  ;media type hello                        Types the text one key at a time, with a screenshot after each.
  ;media key Return                        Presses a key by its xdotool name.
  ;media wait 500                          Waits for that many milliseconds without a screenshot.
  ;media shot                              Takes a screenshot without doing anything.
  ;media shots 8 100                       Takes 8 screenshots, 100 milliseconds apart, for things that move on their own.

  interact.py [--blitzcc PATH] [--only SUBSTRING]
"""
import argparse
import os
import re
import shutil
import subprocess
import sys
import tempfile
import time

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
import wiki  # noqa: E402

TAG = re.compile(r"^;media interact (\S+)(?: (\d+))?\s*$")
STEP = re.compile(r"^;media (click|rclick|move|drag|type|key|wait|shots?)\b ?(.*)$")


def parse(src):
    """Gives the output path, the frame rate and the steps of the script at the top of an example, or None."""
    lines = src.split("\n")
    tag = TAG.match(lines[0])
    if not tag:
        return None
    steps = []
    for line in lines[1:]:
        m = STEP.match(line.rstrip())
        if not m:
            break
        steps.append((m.group(1), m.group(2)))
    return tag.group(1), int(tag.group(2) or 4), steps


def run(*args, **kw):
    return subprocess.run(list(args), capture_output=True, text=True, **kw)


class Session:
    def __init__(self, exe):
        r, w = os.pipe()
        self.xvfb = subprocess.Popen(["Xvfb", "-displayfd", str(w), "-screen", "0", "640x480x24", "-nolisten", "tcp"],
                                     pass_fds=(w,), stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        os.close(w)
        self.display = ":" + os.read(r, 16).decode().strip()
        os.close(r)
        self.env = dict(os.environ, DISPLAY=self.display, XDG_RUNTIME_DIR=tempfile.mkdtemp())
        self.app = subprocess.Popen([exe], env=self.env, stdout=subprocess.DEVNULL, stderr=subprocess.PIPE)
        self.window = None
        for _ in range(100):
            time.sleep(0.1)
            r = run("xdotool", "search", "--pid", str(self.app.pid), env=self.env)
            ids = r.stdout.split()
            if ids:
                self.window = ids[-1]
                break
        if not self.window:
            raise RuntimeError("the program has no window\n" + self.close())
        geo = dict(line.split("=") for line in run("xdotool", "getwindowgeometry", "--shell", self.window,
                                                   env=self.env).stdout.split())
        self.x, self.y, self.w, self.h = int(geo["X"]), int(geo["Y"]), int(geo["WIDTH"]), int(geo["HEIGHT"])
        time.sleep(1.0)
        run("xdotool", "windowfocus", self.window, env=self.env)

    def xdo(self, *args):
        run("xdotool", *args, env=self.env)

    def shot(self, path):
        run("import", "-window", "root", "-crop", "%dx%d+%d+%d" % (self.w, self.h, self.x, self.y), "+repage", path,
            env=self.env)

    def at(self, x, y):
        self.xdo("mousemove", str(self.x + int(x)), str(self.y + int(y)))
        time.sleep(0.15)

    def close(self):
        err = ""
        if self.app.poll() is None:
            self.app.kill()
        err = self.app.stderr.read().decode(errors="replace") if self.app.stderr else ""
        self.xvfb.kill()
        return err


def play(blitzcc, rel, fps, steps, src):
    dest = os.path.join(wiki.WIKI, "media", rel)
    os.makedirs(os.path.dirname(dest), exist_ok=True)
    with tempfile.TemporaryDirectory() as d:
        path = os.path.join(d, "example.bb")
        with open(path, "w", encoding="utf-8") as f:
            f.write(src)
        exe = os.path.join(d, "example")
        r = run(blitzcc, "+q", "-o", exe, path)
        if r.returncode != 0:
            return r.stdout + r.stderr
        frames = []
        s = Session(exe)
        try:
            def shot():
                p = os.path.join(d, "f%04d.png" % len(frames))
                time.sleep(0.2)
                s.shot(p)
                frames.append(p)

            shot()
            for kind, arg in steps:
                n = arg.split()
                if kind in ("click", "rclick"):
                    s.at(n[0], n[1])
                    s.xdo("click", "3" if kind == "rclick" else "1")
                    shot()
                elif kind == "move":
                    s.at(n[0], n[1])
                    shot()
                elif kind == "drag":
                    s.at(n[0], n[1])
                    s.xdo("mousedown", "1")
                    steps_n = 4
                    for i in range(1, steps_n + 1):
                        s.at(int(n[0]) + (int(n[2]) - int(n[0])) * i // steps_n,
                             int(n[1]) + (int(n[3]) - int(n[1])) * i // steps_n)
                    s.xdo("mouseup", "1")
                    shot()
                elif kind == "type":
                    for ch in arg:
                        s.xdo("type", "--delay", "20", ch)
                        shot()
                elif kind == "key":
                    s.xdo("key", arg)
                    shot()
                elif kind == "wait":
                    time.sleep(int(arg) / 1000.0)
                elif kind == "shots":
                    for _ in range(int(n[0])):
                        time.sleep(int(n[1]) / 1000.0)
                        shot()
                else:
                    shot()
        finally:
            err = s.close()
        if not frames:
            return "no screenshot was saved\n" + err
        if dest.endswith(".png"):
            shutil.copyfile(frames[-1], dest)
        else:
            subprocess.run(["ffmpeg", "-v", "error", "-y", "-framerate", str(fps), "-i", os.path.join(d, "f%04d.png"),
                            "-vf", "split[a][b];[a]palettegen=max_colors=64[p];[b][p]paletteuse=dither=none", dest],
                           check=True)
    return ""


def main():
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--blitzcc", default=shutil.which("blitzcc") or os.path.join(wiki.ROOT, "build", "code_compiler",
                                                                                  "blitzcc"))
    ap.add_argument("--only", default="")
    args = ap.parse_args()
    failed = 0
    for c in wiki.load():
        for m in re.finditer(r"```blitzbasic\n(.*?)```", c.text, re.S):
            src = m.group(1)
            parsed = parse(src)
            if not parsed or args.only not in parsed[0]:
                continue
            rel, fps, steps = parsed
            err = play(args.blitzcc, rel, fps, steps, src)
            print("%s %s %s" % ("FAIL" if err else "ok  ", c.name, rel))
            if err:
                failed += 1
                print(err, file=sys.stderr)
    return 1 if failed else 0


if __name__ == "__main__":
    sys.exit(main())
